"""Build the backend Compositions from Python steps."""

import argparse
import ast
import re
import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parents[1]
BACKENDS = ("minio", "aws", "otc", "ovh", "cloudferro")
HEADER = (
    "# Copyright 2026, EOX (https://eox.at) and Versioneer (https://versioneer.at)\n"
    "# SPDX-License-Identifier: Apache-2.0\n\n"
    "# Generated by scripts/build-composition.py. Edit composition/.\n\n"
)


class Dumper(yaml.SafeDumper):
    pass


def represent_string(dumper, value):
    return dumper.represent_scalar(
        "tag:yaml.org,2002:str", value, style="|" if "\n" in value else None
    )


Dumper.add_representer(str, represent_string)


def inline_helpers(script, helper_source, module_name="composition.helpers"):
    helper_tree = ast.parse(helper_source)
    definitions = {}
    for node in helper_tree.body:
        if isinstance(node, ast.FunctionDef):
            definitions[node.name] = node
        elif isinstance(node, (ast.Import, ast.ImportFrom)):
            for alias in node.names:
                definitions[alias.asname or alias.name] = node

    lines = script.splitlines(keepends=True)
    required = set()
    for node in ast.parse(script).body:
        if isinstance(node, ast.ImportFrom) and node.module == module_name:
            for alias in node.names:
                if alias.asname or alias.name not in definitions:
                    raise ValueError(f"Unsupported helper import: {alias.name}")
                required.add(definitions[alias.name])
            lines[node.lineno - 1 : node.end_lineno] = [""] * (
                node.end_lineno - node.lineno + 1
            )

    if not required:
        return script

    pending = list(required)
    while pending:
        for node in ast.walk(pending.pop()):
            dependency = (
                definitions.get(node.id) if isinstance(node, ast.Name) else None
            )
            if dependency is not None and dependency not in required:
                required.add(dependency)
                pending.append(dependency)

    helpers = "\n\n".join(
        ast.get_source_segment(helper_source, node)
        for node in helper_tree.body
        if node in required
    )
    return helpers + "\n\n" + "".join(lines)


def response_ttl_seconds(value):
    match = re.fullmatch(r"([1-9][0-9]*)(s|m|h)", str(value))
    if not match:
        raise ValueError(
            "responseTTL must be a positive whole duration, such as 30s, 5m, or 1h."
        )
    seconds = int(match[1]) * {"s": 1, "m": 60, "h": 3600}[match[2]]
    # Auto-ready uses a signed 64-bit count of nanoseconds.
    if seconds > (2**63 - 1) // 1_000_000_000:
        raise ValueError("responseTTL exceeds the auto-ready duration limit.")
    return seconds


def set_response_ttl(script, seconds):
    functions = [
        node
        for node in ast.parse(script).body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and node.name == "compose"
    ]
    if len(functions) != 1 or len(functions[0].args.args) != 2:
        raise ValueError("A Python step must define one compose(req, rsp) function.")
    function = functions[0]
    first = function.body[0]
    if first.lineno == function.lineno:
        raise ValueError("The compose function body must start on a separate line.")
    request_name, response_name = (arg.arg for arg in function.args.args)
    lines = script.splitlines(keepends=True)
    index = first.lineno - 1
    if ast.get_docstring(function) is not None:
        index = first.end_lineno
    lines.insert(
        index,
        f"{' ' * first.col_offset}if not set_response_ttl("
        f"{request_name}, {response_name}, {seconds}):\n"
        f"{' ' * (first.col_offset + 4)}return\n",
    )
    return "from composition.helpers import set_response_ttl\n\n" + "".join(lines)


def build(backend, root=ROOT, response_ttl=None):
    source = root / "composition"
    settings = yaml.safe_load((source / "settings.yaml").read_text())
    ttl = settings["responseTTL"] if response_ttl is None else response_ttl
    seconds = response_ttl_seconds(ttl)
    for key in ("environmentConfigsTTL", "autoReadyTTL"):
        response_ttl_seconds(settings[key])
    composition = yaml.safe_load((source / backend / "pipeline.yaml").read_text())
    steps = [step["step"] for step in composition["spec"]["pipeline"]]
    if len(steps) != len(set(steps)):
        raise ValueError("Composition pipeline step names must be unique.")
    helpers = (source / "helpers.py").read_text()
    for step in composition["spec"]["pipeline"]:
        data = step.setdefault("input", {})
        function = step["functionRef"]["name"]
        if function == "crossplane-contrib-function-auto-ready":
            data.update(
                apiVersion="autoready.fn.crossplane.io/v1beta1",
                kind="Input",
                ttl=settings["autoReadyTTL"],
            )
        elif function == "function-environment-configs":
            data["ttl"] = settings["environmentConfigsTTL"]
        elif function == "crossplane-contrib-function-python":
            path = (source / data.pop("scriptFile")).resolve()
            path.relative_to(source.resolve())
            script = set_response_ttl(path.read_text(), seconds)
            data["script"] = inline_helpers(script, helpers)
            compile(data["script"], str(path), "exec")
        else:
            raise ValueError(f"No response TTL configuration for function: {function}")
    return HEADER + yaml.dump(composition, Dumper=Dumper, sort_keys=False, width=110)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("backends", nargs="*", metavar="BACKEND", default=BACKENDS)
    parser.add_argument(
        "--check", action="store_true", help="Reject stale generated Compositions."
    )
    parser.add_argument(
        "--response-ttl", help="Override the response TTL for a test build."
    )
    parser.add_argument("--output-dir", type=Path, default=ROOT)
    args = parser.parse_args()
    if any(backend not in BACKENDS for backend in args.backends):
        parser.error("backends must be one of: " + ", ".join(BACKENDS))
    if args.response_ttl and args.output_dir.resolve() == ROOT:
        parser.error("--response-ttl requires a separate --output-dir")
    stale = []
    for backend in args.backends:
        result = build(backend, response_ttl=args.response_ttl)
        target = args.output_dir / backend / "composition.yaml"
        if args.check:
            if not target.is_file() or target.read_text() != result:
                stale.append(str(target.relative_to(args.output_dir)))
        else:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(result)
    if stale:
        print(
            "Stale Compositions: "
            + ", ".join(stale)
            + ". Run python3 scripts/build-composition.py.",
            file=sys.stderr,
        )
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
